import os
import torch
import numpy as np
import random


class Config:
    # ==============================
    # Paths & Directories
    # ==============================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_2"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Metadata Files (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==============================
    # Reproducibility
    # ==============================
    SEED = 42

    # ==============================
    # Data Processing
    # ==============================
    # Resize images to this dimension (min side)
    IMG_SIZE = 800

    # Preprocessing
    USE_CLAHE = True
    CLAHE_CLIP_LIMIT = 2.0
    CLAHE_TILE_GRID_SIZE = (8, 8)

    # Debugging / Data Subsetting
    # Set to a small integer (e.g., 100) to debug the pipeline quickly
    DEBUG = False
    MAX_TRAIN_SAMPLES = None
    MAX_VAL_SAMPLES = None

    # ==============================
    # Model Hyperparameters
    # ==============================
    MODEL_NAME = "fasterrcnn_resnet101_fpn"

    # Detection Classes:
    # 0: Background
    # 1: Typical Appearance
    # 2: Indeterminate Appearance
    # 3: Atypical Appearance
    NUM_DETECTION_CLASSES = 4

    # Study-Level Classes:
    # 0: Negative, 1: Typical, 2: Indeterminate, 3: Atypical
    NUM_STUDY_CLASSES = 4

    # RPN / ROI Heads settings (Increased for dense opacities)
    RPN_PRE_NMS_TOP_N_TRAIN = 3000
    RPN_POST_NMS_TOP_N_TRAIN = 2000
    RPN_PRE_NMS_TOP_N_TEST = 3000
    RPN_POST_NMS_TOP_N_TEST = 2000

    # Loss Weights
    LAMBDA_GLOBAL_CLS = 1.0  # Weight for the auxiliary global classification head

    # ==============================
    # Training Settings
    # ==============================
    BATCH_SIZE = 8
    NUM_EPOCHS = 10
    LEARNING_RATE = 0.005
    MOMENTUM = 0.9
    WEIGHT_DECAY = 0.0005

    # Scheduler
    LR_STEP_SIZE = 8
    LR_GAMMA = 0.1

    # Hardware
    NUM_WORKERS = 4
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # ==============================
    # Inference Settings
    # ==============================
    # Confidence threshold to keep a box prediction
    DETECTION_THRESHOLD = 0.001
    # IoU threshold for NMS
    IOU_THRESHOLD = 0.5

    @classmethod
    def setup(cls):
        """
        Initialize the environment:
        1. Create necessary directories.
        2. Set random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        random.seed(cls.SEED)
        np.random.seed(cls.SEED)
        torch.manual_seed(cls.SEED)

        if torch.cuda.is_available():
            torch.cuda.manual_seed(cls.SEED)
            torch.cuda.manual_seed_all(cls.SEED)

        # Enforce deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False

        print(f"Configuration initialized. Device: {cls.DEVICE}")
